"#!/usr/bin/env python3
"""Build a 4-slide engineering test briefing (report.pptx) from perf_05.csv."""

import csv

from pptx import Presentation
from pptx.util import Inches, Pt

CSV_PATH = "perf_05.csv"
OUT_PATH = "report.pptx"
COLS = ["config", "cl_max", "cd_cruise", "ld_ratio"]


def norm(s):
    return "".join(ch for ch in str(s).strip().lower() if ch.isalnum())


def load_records(path):
    """Return records as lists of [config, cl_max, cd_cruise, ld_ratio] strings."""
    with open(path, newline="", encoding="utf-8-sig") as f:
        raw = [r for r in csv.reader(f) if r and any(str(c).strip() for c in r)]
    if not raw:
        raise SystemExit(f"No usable rows found in {path}")

    target = {norm(c): c for c in COLS}
    idx = {}
    for j, h in enumerate(raw[0]):
        key = norm(h)
        if key in target and target[key] not in idx:
            idx[target[key]] = j

    if len(idx) == len(COLS):
        body = raw[1:]
        records = [
            [str(r[idx[c]]).strip() for c in COLS]
            for r in body
            if len(r) >= 4
        ]
    else:
        # Positional fallback: assume the first four columns are in the required order.
        records = [
            [str(r[i]).strip() for i in range(4)]
            for r in raw
            if len(r) >= 4
        ]

    if not records:
        raise SystemExit("No data records found in CSV.")
    return records


def to_f(value):
    try:
        return float(str(value).strip())
    except (TypeError, ValueError):
        return None


def set_cell_text(cell, text, size_pt, bold=False):
    cell.text = str(text)
    for para in cell.text_frame.paragraphs:
        for run in para.runs:
            run.font.size = Pt(size_pt)
            run.font.bold = bold


def fill_bullets(slide, lines, size_pt=20):
    body = slide.placeholders[1]
    tf = body.text_frame
    tf.clear()
    for i, line in enumerate(lines):
        p = tf.paragraphs[0] if i == 0 else tf.add_paragraph()
        p.text = line
        for run in p.runs:
            run.font.size = Pt(size_pt)


def main():
    records = load_records(CSV_PATH)

    cl_vals = [v for v in (to_f(r[1]) for r in records) if v is not None]
    cd_vals = [v for v in (to_f(r[2]) for r in records) if v is not None]
    ld_vals = [v for v in (to_f(r[3]) for r in records) if v is not None]
    if not (cl_vals and cd_vals and ld_vals):
        raise SystemExit("Could not parse numeric columns from CSV.")

    clmax_max = max(cl_vals)
    cd_mean = sum(cd_vals) / len(cd_vals)
    ld_mean = sum(ld_vals) / len(ld_vals)
    max_ld = max(ld_vals)
    best_cfg = next(r[0] for r in records if to_f(r[3]) == max_ld)

    # Rounded display values exactly as specified.
    clmax_txt = f"{clmax_max:.3f}"
    cd_mean_txt = f"{cd_mean:.4f}"
    ld_mean_txt = f"{ld_mean:.1f}"

    prs = Presentation()
    prs.slide_width = Inches(10)
    prs.slide_height = Inches(7.5)

    # ---- Slide 1: Title -------------------------------------------------
    s1 = prs.slides.add_slide(prs.slide_layouts[0])
    s1.shapes.title.text = "Engineering Test Briefing"
    if len(s1.placeholders) > 1:
        s1.placeholders[1].text = "Aerodynamic performance review (perf_05)"

    # ---- Slide 2: Data table --------------------------------------------
    s2 = prs.slides.add_slide(prs.slide_layouts[5])
    s2.shapes.title.text = "Data"
    n = len(records)
    font_pt = 14 if n <= 8 else (11 if n <= 18 else 9)
    gfx = s2.shapes.add_table(
        n + 1, 4, Inches(0.7), Inches(1.5), Inches(8.6), Inches(0.35 * (n + 1))
    )
    table = gfx.table
    for j, w in enumerate([Inches(2.2), Inches(2.2), Inches(2.2), Inches(2.0)]):
        table.columns[j].width = w
    for j, name in enumerate(COLS):
        set_cell_text(table.cell(0, j), name, font_pt, bold=True)
    for i, rec in enumerate(records, start=1):
        for j, val in enumerate(rec):
            set_cell_text(table.cell(i, j), val, font_pt)

    # ---- Slide 3: Summary --------------------"
